
import { MatDialog } from '@angular/material/dialog';
import { Component, OnInit } from '@angular/core';
import { AnswerType, Category, Question, QuestionType, Turn } from '../utils';
import { CardDialogComponent } from '../card-dialog/card-dialog.component';
import { brideQuestions, coupleQuestions, groomQuestions, randomQuestions } from '../questions';

const score1Key= 'score1'
const score2Key= 'score2'
const brideKey ='bride'
const groomKey ='groom'
const coupleKey ='couple'
const randomKey ='random'
@Component({
  selector: 'app-game-board',
  templateUrl: './game-board.component.html',
  styleUrls: ['./game-board.component.scss']
})
export class GameBoardComponent implements OnInit{
  title = 'jlogame';
  QuestionType = QuestionType
  Turn = Turn
  Category = Category
  score1 =0
  score2 = 0
  turn = Turn.team1
  constructor(private dialog:MatDialog){}
  ngOnInit(): void {
    let score1 = localStorage.getItem(score1Key)
    let score2 = localStorage.getItem(score2Key)
    this.score1 = score1!= null ? parseInt(score1) :0
    this.score2 = score2!= null ? parseInt(score2) :0

    let brideVal = localStorage.getItem(brideKey)
    let groomVal = localStorage.getItem(groomKey)
    let coupleVal = localStorage.getItem(coupleKey)
    let randomVal = localStorage.getItem(randomKey)

    this.bride = brideVal != null ? JSON.parse(brideVal) : brideQuestions
    this.groom = groomVal != null ? JSON.parse(groomVal) : groomQuestions
    this.couple = coupleVal != null ? JSON.parse(coupleVal) : coupleQuestions
    this.random = randomVal != null ? JSON.parse(randomVal) : randomQuestions
    
  }

  bride:Question[] =[]
  groom:Question[] = []
  couple:Question[] = []
  random:Question[] = []

  showQuestion(category:Category, index:number){
    let questions:Question[] = [] 
    switch(category){
      case Category.bride: questions = this.bride; break
      case Category.groom: questions = this.groom; break
      case Category.couple: questions = this.couple; break
      case Category.random: questions = this.random; break
    }
    let question = questions[index]
    let dialogRef = this.dialog.open(CardDialogComponent, {data:question, // Optional, but makes the size nice
      disableClose: true})
    dialogRef.afterClosed().subscribe((val)=>{
      switch(val){
        case AnswerType.correct:{
          this.activeScore = this.activeScore + question.points
          break
        }
        case AnswerType.half:{
          this.activeScore = this.activeScore + question.points / 2
          break
        }
      }
      this.turn = this.turn == Turn.team1 ? Turn.team2 : Turn.team1
      question.used = true
      this.persistState()
    })
  }
  get activeScore(): number {
    return this.turn === Turn.team1 ? this.score1 : this.score2;
  }
  set activeScore(value: number) {
    if (this.turn === Turn.team1) {
      this.score1 = value;
    } else {
      this.score2 = value;
    }
  }

  persistState(){
    localStorage.setItem(score1Key, this.score1.toString())
    localStorage.setItem(score2Key, this.score2.toString())
    localStorage.setItem(brideKey, JSON.stringify(this.bride))
    localStorage.setItem(groomKey, JSON.stringify(this.groom))
    localStorage.setItem(coupleKey, JSON.stringify(this.couple))
    localStorage.setItem(randomKey, JSON.stringify(this.random))
  }
  clear(){
    localStorage.clear()
  }
}
